      # Generated by Workroom — active theme for the current appearance. Do not edit.
      theme = "\(theme)"
      window-padding-x = 8
      window-padding-y = 8
      window-padding-balance = true
      """
    try? contents.write(to: themeConfigURL, atomically: true, encoding: .utf8)
